import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  resultCodeActionsActionResultCodeSchema,
  type ResultCodeActionsActionResultCode,
} from "./result-code-actions-action-result-code.js";
import {
  typeActionsActionTypeActionsSchema,
  type TypeActionsActionTypeActions,
} from "./type-actions-action-type-actions.js";

export type Action9 = {
  /** A unique identifier generated by Global Payments to identify an action. */
  id?: string;
  /**
   * Indicates the specific action taken.
   *   * `ACTION_LIST` - Get a list of actions
   *   * `ACTION_SINGLE` - Get a single action
   */
  type?: TypeActionsActionTypeActions;
  /** Global Payments time indicating when the object was created in ISO-8601 format. */
  timeCreated?: string;
  /** The result of the action executed. */
  resultCode?: ResultCodeActionsActionResultCode;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const action9Schema: Schema<Action9> = s.object<Action9>(
  {
    id: s.optional(s.string()),
    type: s.optional(s.lazy(() => typeActionsActionTypeActionsSchema)),
    timeCreated: s.optional(s.string()),
    resultCode: s.optional(s.lazy(() => resultCodeActionsActionResultCodeSchema)),
    appId: s.optional(s.string()),
    appName: s.optional(s.string()),
    _keysMap: {
      timeCreated: "time_created",
      resultCode: "result_code",
      appId: "app_id",
      appName: "app_name",
    },
  },
  { additionalProperties: s.json() },
);
